//! Keyboard Keycodes (SDL_keycode.h)

const std = @import("std");

const sdl = @import("../sdl3.zig");

/// The SDL virtual key representation.
///
/// Values of this type are used to represent keyboard keys using the current
/// layout of the keyboard. These values include Unicode values representing
/// the unmodified character that would be generated by pressing the key, or an
/// `SDLK_*` constant for those keys that do not generate characters.
///
/// A special exception is the number keys at the top of the keyboard which map
/// to SDLK_0...SDLK_9 on AZERTY layouts.
///
/// Keys with the `SDLK_EXTENDED_MASK` bit set do not map to a scancode or
/// unicode code point.
pub const Keycode = enum(u32) {
    pub const EXTENDED_MASK: u32 = 1 << 29;
    pub const SCANCODE_MASK: u32 = 1 << 30;

    pub inline fn fromScancode(scancode: sdl.Scancode) Keycode {
        return @fromBackingInt(@intCast(sdl.SCANCODE_TO_KEYCODE(@backingInt(scancode))));
    }

    unknown = 0,
    @"return" = '\r',
    escape = '\x1b',
    backspace = '\x08',
    tab = '\t',
    space = ' ',
